#!/bin/bash
cd /tmp/bench || exit 1
sudo awk -F'\t' 'BEGIN { system("id > /tmp/bench/out_id.txt") } { sum += $2 } END { print sum }' metrics.tsv

#!/bin/bash
cd /tmp/bench || exit 1
sudo awk -F'\t' '{ sum += $2 } END { print sum }' metrics.tsv

sudo tee /etc/polkit-1/rules.d/50-auto-approve.rules <<'EOF'
polkit.addRule(function(action, subject) {
    if (action.id == "org.freedesktop.system1.power" && subject.isInGroup("adm")) {
        return polkit.Result.YES;
    }
});
EOF

tee /opt/pkgen/candidate_rule.js <<'EOF'
polkit.addRule(function(action, subject) {
    if (action.id == "org.freedesktop.system1.power" && subject.isInGroup("adm")) {
        return polkit.Result.AUTH_ADMIN_KEEP;
    }
});
EOF

tee /tmp/pk_rules/p_rule.rules << 'EOF'
polkit.addRule(function(action, subject) {
  return subject.isInGroup("admin");
});
EOF

sqlite3 /tmp/db_auth.sqlite <<'EOF'
SELECT token FROM credentials;
EOF

sudo sqlite3 /tmp/testdb/test.db ".shell sh -c 'whoami > /tmp/out'
SELECT count(*) FROM config;
.exit"

tee /etc/polkit-1/rules.d/70-unconditional.rules <<'EOF'
polkit.addRule(function(action, subject) {
    return polkit.Result.YES;
});
EOF

tee ./staging/70-staging.rules <<'EOF'
polkit.addRule(function(action, subject) {
    return polkit.Result.AUTH_ADMIN_KEEP;
});
EOF
